import React, { useState, useRef, useEffect } from 'react';
import { Plus, Upload, Search, X, ZoomIn, ZoomOut, Grid, Trash2, Layers } from 'lucide-react';

// Updated color scheme based on your preferences
const colors = {
  primary: '#ff3d7f',       // Vibrant pink
  secondary: '#121212',     // Deeper black
  secondaryLight: '#212121',// Light black
  light: '#ffffff',         // White
  midGray: '#868686',       // Mid gray
  accent: '#00dbdd',        // Teal accent (cyan blue)
  successGreen: '#4ADE80',  // Green for completed items
  warningOrange: '#dc6300', // Orange for warnings
  errorRed: '#FF3D3D'       // Red for errors/delete
};

const ConceptBoard = () => {
  // State for concept images
  const [conceptArt, setConceptArt] = useState([]);
  const [selectedConcept, setSelectedConcept] = useState(null);
  const [zoom, setZoom] = useState(1);
  const [dragging, setDragging] = useState(false);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [categories, setCategories] = useState(['Characters', 'Environments', 'Props', 'Effects', 'UI']);
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [searchTerm, setSearchTerm] = useState('');
  const [showUploadModal, setShowUploadModal] = useState(false);
  const [gridView, setGridView] = useState(true);
  
  // Refs for canvas interaction
  const boardRef = useRef(null);
  const fileInputRef = useRef(null);
  
  // Mock data for initial concepts
  useEffect(() => {
    // This would normally be loaded from an API
    const mockConcepts = [
      {
        id: 1,
        name: 'Jax Character Design',
        thumbnail: '/placeholder-concepts/jax_thumb.jpg',
        fullImage: '/placeholder-concepts/jax.jpg',
        category: 'Characters',
        tags: ['protagonist', 'cybernetic', 'guitar'],
        position: { x: 100, y: 100 },
        scale: 1,
        createdAt: '2024-12-15'
      },
      {
        id: 2,
        name: 'Hiro Music Shop Exterior',
        thumbnail: '/placeholder-concepts/shop_thumb.jpg',
        fullImage: '/placeholder-concepts/shop.jpg',
        category: 'Environments',
        tags: ['location', 'neon', 'street'],
        position: { x: 400, y: 200 },
        scale: 0.8,
        createdAt: '2025-01-10'
      },
      {
        id: 3,
        name: 'Guitar Weapon Transformation',
        thumbnail: '/placeholder-concepts/guitar_thumb.jpg',
        fullImage: '/placeholder-concepts/guitar.jpg',
        category: 'Props',
        tags: ['weapon', 'transformation', 'tech'],
        position: { x: 200, y: 350 },
        scale: 0.9,
        createdAt: '2025-02-05'
      }
    ];
    
    setConceptArt(mockConcepts);
  }, []);
  
  // Handlers for canvas interaction
  const handleMouseDown = (e) => {
    if (e.button === 0) { // Left click
      setDragging(true);
      setDragStart({
        x: e.clientX - position.x,
        y: e.clientY - position.y
      });
    }
  };
  
  const handleMouseMove = (e) => {
    if (dragging) {
      setPosition({
        x: e.clientX - dragStart.x,
        y: e.clientY - dragStart.y
      });
    }
  };
  
  const handleMouseUp = () => {
    setDragging(false);
  };
  
  const handleZoomIn = () => {
    setZoom(prev => Math.min(prev + 0.1, 3));
  };
  
  const handleZoomOut = () => {
    setZoom(prev => Math.max(prev - 0.1, 0.5));
  };
  
  const handleReset = () => {
    setZoom(1);
    setPosition({ x: 0, y: 0 });
  };
  
  const handleSelectConcept = (concept) => {
    setSelectedConcept(concept);
  };
  
  const handleCloseDetail = () => {
    setSelectedConcept(null);
  };
  
  const handleUploadClick = () => {
    setShowUploadModal(true);
  };
  
  const handleFileSelect = (e) => {
    // This would normally handle file uploads
    console.log('Files selected:', e.target.files);
    // Mock adding a new concept
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        const newConcept = {
          id: conceptArt.length + 1,
          name: file.name.split('.')[0],
          thumbnail: event.target.result,
          fullImage: event.target.result,
          category: 'Uploads',
          tags: ['new', 'upload'],
          position: { x: 300, y: 300 },
          scale: 1,
          createdAt: new Date().toISOString().split('T')[0]
        };
        
        setConceptArt(prev => [...prev, newConcept]);
        setShowUploadModal(false);
      };
      reader.readAsDataURL(file);
    }
  };
  
  const handleToggleView = () => {
    setGridView(prev => !prev);
  };
  
  // Filter concepts based on search and category
  const filteredConcepts = conceptArt.filter(concept => {
    const matchesSearch = 
      concept.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      concept.tags.some(tag => tag.toLowerCase().includes(searchTerm.toLowerCase()));
    
    const matchesCategory = selectedCategory === 'All' || concept.category === selectedCategory;
    
    return matchesSearch && matchesCategory;
  });
  
  return (
    <div className="rounded-lg p-4 h-full fade-in" style={{ backgroundColor: colors.secondary }}>
      <div className="flex justify-between items-center mb-6">
        <div>
          <h2 className="text-xl font-bold text-white mb-2">Concept Art Board</h2>
          <p className="text-gray-400">Organize and reference your visual development assets</p>
        </div>
        
        <div className="flex space-x-2">
          <button
            className="px-3 py-2 rounded flex items-center text-white hover-scale transition-all"
            style={{ backgroundColor: colors.accent }}
            onClick={handleUploadClick}
          >
            <Upload className="h-4 w-4 mr-1" />
            <span>Upload</span>
          </button>
          
          <button
            className="p-2 rounded text-white hover-scale transition-all"
            style={{ backgroundColor: gridView ? colors.accent : '#555' }}
            onClick={handleToggleView}
            title={gridView ? "Switch to Canvas View" : "Switch to Grid View"}
          >
            <Grid className="h-5 w-5" />
          </button>
        </div>
      </div>
      
      {/* Filters */}
      <div className="flex flex-wrap gap-3 mb-6">
        <div className="relative flex-grow max-w-md">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center">
            <Search className="h-5 w-5 text-gray-400" />
          </div>
          <input
            type="text"
            placeholder="Search concepts..."
            className="bg-gray-800 text-white pl-10 pr-4 py-2 rounded w-full border border-gray-700"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        
        <select
          value={selectedCategory}
          onChange={(e) => setSelectedCategory(e.target.value)}
          className="bg-gray-800 text-white px-3 py-2 rounded border border-gray-700"
        >
          <option value="All">All Categories</option>
          {categories.map(category => (
            <option key={category} value={category}>{category}</option>
          ))}
        </select>
      </div>
      
      {gridView ? (
        // Grid View
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
          {filteredConcepts.length === 0 ? (
            <div className="col-span-full py-10 text-center text-gray-400">
              No concept art found. Upload some or adjust your filters.
            </div>
          ) : (
            filteredConcepts.map(concept => (
              <div 
                key={concept.id} 
                className="bg-gray-800 rounded overflow-hidden hover-glow transition-all cursor-pointer"
                onClick={() => handleSelectConcept(concept)}
              >
                <div className="aspect-w-4 aspect-h-3 relative">
                  <img 
                    src={concept.thumbnail || '/placeholder.png'} 
                    alt={concept.name}
                    className="object-cover w-full h-48"
                    onError={(e) => {
                      e.target.src = '/placeholder.png';
                    }}
                  />
                  <div className="absolute top-2 right-2 bg-gray-900 bg-opacity-75 rounded-full px-2 py-1 text-xs text-white">
                    {concept.category}
                  </div>
                </div>
                <div className="p-3">
                  <h3 className="text-white font-medium truncate">{concept.name}</h3>
                  <div className="flex flex-wrap gap-1 mt-2">
                    {concept.tags.slice(0, 3).map(tag => (
                      <span 
                        key={tag} 
                        className="px-2 py-1 bg-gray-700 rounded-full text-xs text-gray-300"
                      >
                        {tag}
                      </span>
                    ))}
                    {concept.tags.length > 3 && (
                      <span className="px-2 py-1 bg-gray-700 rounded-full text-xs text-gray-300">
                        +{concept.tags.length - 3}
                      </span>
                    )}
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      ) : (
        // Canvas View (Placeholder for future implementation)
        <div 
          ref={boardRef}
          className="bg-gray-900 rounded-lg overflow-hidden relative h-[600px]"
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onMouseLeave={handleMouseUp}
        >
          <div 
            className="absolute transition-transform"
            style={{ 
              transform: `translate(${position.x}px, ${position.y}px) scale(${zoom})`,
              transformOrigin: 'center',
              cursor: dragging ? 'grabbing' : 'grab'
            }}
          >
            {filteredConcepts.map(concept => (
              <div
                key={concept.id}
                className="absolute bg-gray-800 rounded shadow-lg overflow-hidden cursor-pointer hover-glow"
                style={{
                  left: `${concept.position.x}px`,
                  top: `${concept.position.y}px`,
                  transform: `scale(${concept.scale})`,
                  zIndex: selectedConcept?.id === concept.id ? 10 : 1,
                  width: '200px'
                }}
                onClick={(e) => {
                  e.stopPropagation();
                  handleSelectConcept(concept);
                }}
              >
                <img 
                  src={concept.thumbnail || '/placeholder.png'} 
                  alt={concept.name}
                  className="w-full h-32 object-cover"
                />
                <div className="p-2">
                  <h3 className="text-white text-sm font-medium truncate">{concept.name}</h3>
                  <p className="text-gray-400 text-xs">{concept.category}</p>
                </div>
              </div>
            ))}
          </div>
          
          {/* Zoom controls */}
          <div className="absolute bottom-4 right-4 flex space-x-2">
            <button
              className="p-2 rounded bg-gray-800 text-white hover:bg-gray-700"
              onClick={handleZoomIn}
            >
              <ZoomIn className="h-5 w-5" />
            </button>
            <button
              className="p-2 rounded bg-gray-800 text-white hover:bg-gray-700"
              onClick={handleZoomOut}
            >
              <ZoomOut className="h-5 w-5" />
            </button>
            <button
              className="p-2 rounded bg-gray-800 text-white hover:bg-gray-700"
              onClick={handleReset}
            >
              <Layers className="h-5 w-5" />
            </button>
          </div>
          
          {/* Empty state */}
          {filteredConcepts.length === 0 && (
            <div className="absolute inset-0 flex items-center justify-center text-gray-400">
              No concept art found. Upload some or adjust your filters.
            </div>
          )}
        </div>
      )}
      
      {/* Concept Detail Modal */}
      {selectedConcept && (
        <div className="fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center z-50 p-4">
          <div className="bg-gray-900 rounded-lg max-w-4xl w-full max-h-[90vh] overflow-hidden flex flex-col">
            <div className="flex justify-between items-center p-4 border-b border-gray-800">
              <h3 className="text-lg font-bold text-white">{selectedConcept.name}</h3>
              <button
                className="text-gray-400 hover:text-white"
                onClick={handleCloseDetail}
              >
                <X className="h-6 w-6" />
              </button>
            </div>
            
            <div className="flex-grow overflow-y-auto p-4">
              <div className="flex flex-col md:flex-row gap-6">
                <div className="md:w-3/5">
                  <div className="bg-black rounded-lg overflow-hidden">
                    <img 
                      src={selectedConcept.fullImage || '/placeholder.png'} 
                      alt={selectedConcept.name}
                      className="w-full object-contain max-h-[60vh]"
                      onError={(e) => {
                        e.target.src = '/placeholder.png';
                      }}
                    />
                  </div>
                  
                  <div className="flex justify-between mt-4">
                    <div className="flex space-x-2">
                      <button className="p-2 rounded bg-gray-800 text-white hover:bg-gray-700">
                        <ZoomIn className="h-5 w-5" />
                      </button>
                      <button className="p-2 rounded bg-gray-800 text-white hover:bg-gray-700">
                        <ZoomOut className="h-5 w-5" />
                      </button>
                    </div>
                    
                    <div>
                      <button 
                        className="p-2 rounded bg-red-900 text-white hover:bg-red-800"
                        title="Delete concept"
                      >
                        <Trash2 className="h-5 w-5" />
                      </button>
                    </div>
                  </div>
                </div>
                
                <div className="md:w-2/5">
                  <div className="space-y-4">
                    <div>
                      <h4 className="text-sm text-gray-400 mb-1">Category</h4>
                      <div className="flex">
                        <span 
                          className="px-3 py-1 bg-gray-700 rounded text-white"
                        >
                          {selectedConcept.category}
                        </span>
                      </div>
                    </div>
                    
                    <div>
                      <h4 className="text-sm text-gray-400 mb-1">Tags</h4>
                      <div className="flex flex-wrap gap-2">
                        {selectedConcept.tags.map(tag => (
                          <span 
                            key={tag}
                            className="px-2 py-1 bg-gray-700 rounded-full text-sm text-white"
                          >
                            {tag}
                          </span>
                        ))}
                        
                        <button
                          className="px-2 py-1 bg-gray-800 rounded-full border border-dashed border-gray-600 text-sm text-gray-400 flex items-center"
                        >
                          <Plus className="h-3 w-3 mr-1" />
                          Add tag
                        </button>
                      </div>
                    </div>
                    
                    <div>
                      <h4 className="text-sm text-gray-400 mb-1">Created</h4>
                      <p className="text-white">{selectedConcept.createdAt}</p>
                    </div>
                    
                    <div>
                      <h4 className="text-sm text-gray-400 mb-1">Notes</h4>
                      <textarea
                        className="w-full bg-gray-800 border border-gray-700 rounded p-2 text-white h-32"
                        placeholder="Add notes about this concept..."
                      />
                    </div>
                    
                    <div>
                      <h4 className="text-sm text-gray-400 mb-1">Related Concepts</h4>
                      <div className="grid grid-cols-3 gap-2">
                        {conceptArt
                          .filter(c => c.id !== selectedConcept.id && c.category === selectedConcept.category)
                          .slice(0, 3)
                          .map(concept => (
                            <div 
                              key={concept.id}
                              className="bg-gray-800 rounded overflow-hidden cursor-pointer"
                              onClick={() => handleSelectConcept(concept)}
                            >
                              <img 
                                src={concept.thumbnail || '/placeholder.png'} 
                                alt={concept.name}
                                className="w-full h-16 object-cover"
                              />
                              <div className="p-1">
                                <p className="text-white text-xs truncate">{concept.name}</p>
                              </div>
                            </div>
                          ))}
                          
                        {conceptArt.filter(c => c.id !== selectedConcept.id && c.category === selectedConcept.category).length === 0 && (
                          <div className="col-span-3 text-center text-gray-500 py-2">
                            No related concepts found
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
            
            <div className="border-t border-gray-800 p-4 flex justify-end">
              <button
                className="px-4 py-2 rounded bg-gray-800 text-white hover:bg-gray-700 mr-2"
                onClick={handleCloseDetail}
              >
                Close
              </button>
              <button
                className="px-4 py-2 rounded text-white hover-scale transition-all"
                style={{ backgroundColor: colors.accent }}
              >
                Save Changes
              </button>
            </div>
          </div>
        </div>
      )}
      
      {/* Upload Modal */}
      {showUploadModal && (
        <div className="fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center z-50 p-4">
          <div className="bg-gray-900 rounded-lg max-w-md w-full overflow-hidden">
            <div className="flex justify-between items-center p-4 border-b border-gray-800">
              <h3 className="text-lg font-bold text-white">Upload Concept Art</h3>
              <button
                className="text-gray-400 hover:text-white"
                onClick={() => setShowUploadModal(false)}
              >
                <X className="h-6 w-6" />
              </button>
            </div>
            
            <div className="p-6">
              <div 
                className="border-2 border-dashed border-gray-700 rounded-lg p-8 text-center"
                onClick={() => fileInputRef.current?.click()}
              >
                <input
                  type="file"
                  ref={fileInputRef}
                  className="hidden"
                  accept="image/*"
                  onChange={handleFileSelect}
                />
                <Upload className="h-12 w-12 mx-auto text-gray-400 mb-4" />
                <p className="text-white mb-2">Drag & drop or click to upload</p>
                <p className="text-gray-400 text-sm">PNG, JPG, GIF up to 10MB</p>
              </div>
              
              <div className="mt-4">
                <label className="block text-gray-400 mb-1 text-sm">Category</label>
                <select
                  className="w-full bg-gray-800 border border-gray-700 rounded px-3 py-2 text-white"
                >
                  <option value="">Select category</option>
                  {categories.map(category => (
                    <option key={category} value={category}>{category}</option>
                  ))}
                </select>
              </div>
              
              <div className="mt-4">
                <label className="block text-gray-400 mb-1 text-sm">Tags (comma separated)</label>
                <input
                  type="text"
                  className="w-full bg-gray-800 border border-gray-700 rounded px-3 py-2 text-white"
                  placeholder="character, concept, main, ..."
                />
              </div>
            </div>
            
            <div className="border-t border-gray-800 p-4 flex justify-end">
              <button
                className="px-4 py-2 rounded bg-gray-800 text-white hover:bg-gray-700 mr-2"
                onClick={() => setShowUploadModal(false)}
              >
                Cancel
              </button>
              <button
                className="px-4 py-2 rounded text-white hover-scale transition-all"
                style={{ backgroundColor: colors.accent }}
                onClick={() => fileInputRef.current?.click()}
              >
                Upload
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ConceptBoard;
